export const code = async (inputs) => {
  // Русский-онли до платформенного i18n — ADR-0014.
  // ИСТОЧНИК ТЕКСТА — i18n/ru.json. Правка формулировки — это правка ru.json
  // И входа этого шага; иначе они разъедутся молча (ловит check-texts.py).
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const tgt = (inputs.target && typeof inputs.target === 'object') ? inputs.target : {};
  const kind = str(tgt.kind) === '2h' ? '2h' : '24h';
  const text = t(kind === '2h' ? 'remind.2h' : 'remind.24h', { title: str(tgt.title), when: str(tgt.when), address: str(tgt.address) });
  return { text: text, kind: kind };
};

