export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const byEvent = {};
  (Array.isArray(inputs.due) ? inputs.due : []).forEach((d) => { if (d && str(d.eventId) !== '') byEvent[str(d.eventId)] = d; });
  // Получатели — только status=registered. Отбор повторяется в коде (Q25):
  // фильтр чтения может разойтись, решение — по полям записи.
  const seen = {};
  const targets = arr(inputs.regs).map(flat)
    .filter((r) => str(r.status) === 'registered' && byEvent[str(r.event_id)] && str(r.telegram_id) !== '')
    .filter((r) => { const k = str(r.event_id) + '|' + str(r.telegram_id); if (seen[k]) return false; seen[k] = true; return true; })
    .map((r) => { const d = byEvent[str(r.event_id)]; return { eventId: str(r.event_id), kind: str(d.kind), telegramId: str(r.telegram_id), title: str(d.title), when: str(d.when), address: str(d.address) }; });
  return { targets: targets, count: targets.length };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parse = (s) => { if (!s) return NaN; return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z'); };
  // Показ — Asia/Tashkent словами (OWN-3), тот же набор опций, что в manage-api.
  const WHEN_FMT = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

  const H = 3600 * 1000;
  const now = Date.now();
  const due = [];
  arr(inputs.events).map(flat)
    .filter((e) => str(e.status) === 'published' && str(e.id) !== '')
    .forEach((e) => {
      const ms = parse(str(e.starts_at));
      if (!isFinite(ms)) return;
      const dt = ms - now;
      // Окна OWN-16: 24h iff 2h<dt<=24h, 2h iff 0<dt<=2h. В момент старта —
      // ничего; пропущенное окно не досылается (dt<=0 — пропуск навсегда).
      // Ивент, опубликованный поздно (dt уже <2h), вид 24h не получит никогда.
      let kind = '';
      if (dt > 2 * H && dt <= 24 * H) kind = '24h';
      else if (dt > 0 && dt <= 2 * H) kind = '2h';
      else return;
      due.push({ eventId: str(e.id), title: str(e.title), startsAt: str(e.starts_at), address: str(e.address), kind: kind, when: WHEN_FMT.format(new Date(ms)) });
    });
  const seen = {};
  const ids = due.map((d) => d.eventId).filter((id) => { if (seen[id]) return false; seen[id] = true; return true; });
  return { nowIso: new Date(now).toISOString(), due: due, dueCount: due.length, dueIdsCsv: ids.length ? ids.join(',') : '__none__' };
};
